   106→/**
   107→ * Classify population outcome based on 7-tier system (Oct 13, 2025)
   108→ * Historical precedents: Black Death (30-60% mortality, recovered), 
   109→ * Toba Supervolcano (~99.9% mortality, humanity survived)
   110→ */
   111→function classifyPopulationOutcome(
   112→  currentPop: number, 
   113→  initialPop: number,
   114→  state: GameState
   115→): OutcomeType {
   116→  const mortality = 1 - (currentPop / initialPop);
   117→  const currentPeople = currentPop * 1_000_000_000;
   118→  
   119→  // EXTINCTION: <10K people OR >99.99% mortality
   120→  if (currentPeople < 10_000 || mortality > 0.9999) {
   121→    console.log(`   💀 EXTINCTION: Humanity extinct (${currentPeople.toFixed(0)} people, ${(mortality * 100).toFixed(2)}% mortality)\n`);
   122→    return 'extinction';
   123→  }
   124→  
   125→  // TERMINAL: 98.75-99.99% mortality (1M-100M people)
   126→  if (mortality > 0.9875 || currentPeople < 100_000_000) {
   127→    // Check if cascading crises make recovery impossible
   128→    if (hasIrreversibleCascade(state)) {
   129→      console.log(`   ⚰️  TERMINAL: Extinction likely (${(currentPeople / 1_000_000).toFixed(1)}M people, ${(mortality * 100).toFixed(1)}% mortality, irreversible cascade)\n`);
   130→      return 'terminal';
   131→    }
   132→    console.log(`   🧬 BOTTLENECK: Genetic bottleneck (${(currentPeople / 1_000_000).toFixed(1)}M people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   133→    return 'bottleneck';
   134→  }
   135→  
   136→  // BOTTLENECK: 87.5-98.75% mortality (100M-1B people)
   137→  if (mortality > 0.875 || currentPeople < 1_000_000_000) {
   138→    console.log(`   🧬 BOTTLENECK: Genetic bottleneck (${(currentPeople / 1_000_000).toFixed(0)}M people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   139→    return 'bottleneck';
   140→  }
   141→  
   142→  // DARK AGE: 50-87.5% mortality (1B-4B people)
   143→  if (mortality > 0.50) {
   144→    // Check if civilization systems collapsed
   145→    if (hasCivilizationCollapse(state)) {
   146→      console.log(`   🏚️  DARK AGE: Civilization collapse (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   147→      return 'dark_age';
   148→    }
   149→    console.log(`   💥 COLLAPSE: Major systems failing (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   150→    return 'collapse';
   151→  }
   152→  
   153→  // COLLAPSE: 20-50% mortality (4B-6.4B people)
   154→  if (mortality > 0.20) {
   155→    console.log(`   💥 COLLAPSE: Major crisis (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   156→    return 'collapse';
   157→  }
   158→  
   159→  // CRISIS ERA: 10-20% mortality (6.4B-7.2B people)
   160→  if (mortality > 0.10) {
   161→    console.log(`   ⚠️  CRISIS ERA: Significant challenges (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   162→    return 'crisis_era';
   163→  }
   164→  
   165→  // STATUS QUO: 0-10% mortality (7.2B-8B people)
   166→  console.log(`   📊 STATUS QUO: Normal trajectory (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   167→  return 'status_quo';
   168→}
   169→
   170→/**
   171→ * Check if environmental cascade is irreversible
   172→ */
   173→function hasIrreversibleCascade(state: GameState): boolean {
   174→  const cascade = state.planetaryBoundariesSystem;
   175→  const env = state.environmentalAccumulation;
   176→  
   177→  // Check for conditions that make recovery impossible
   178→  return (
   179→    (cascade.cascadeSeverity > 0.8) &&  // Severe cascade
   180→    (env.foodSecurity < 0.2) &&          // Catastrophic food failure
   181→    (env.biodiversityIndex < 0.15)       // Ecosystem collapse
   182→  );
   183→}
   184→
   185→/**
   186→ * Check if civilization has collapsed (not just population decline)
   187→ */
   188→function hasCivilizationCollapse(state: GameState): boolean {
   189→  const social = state.socialAccumulation;
   190→  const tech = state.technologicalRisk;
   191→  
   192→  // Check if institutions and infrastructure collapsed
   193→  const institutionalCollapse = social.institutionalFailureActive;
   194→  const aiTakeover = tech.controlLossActive && 
   195→    state.aiAgents.filter(ai => ai.alignment < 0.3 && ai.capability > 2.0).length > 10;
   196→  
   197→  return institutionalCollapse || aiTakeover;
   198→}
