   200→/**
   201→ * Seedable random number generator for reproducible simulations
   202→ */
   203→export class SeededRandom {
   204→  private seed: number;
   205→  
   206→  constructor(seed: number) {
   207→    this.seed = seed;
   208→  }
   209→  
   210→  /**
   211→   * Generate next random number [0, 1)
   212→   */
   213→  next(): number {
   214→    // Simple LCG (Linear Congruential Generator)
   215→    this.seed = (this.seed * 1664525 + 1013904223) % 2**32;
   216→    return this.seed / 2**32;
   217→  }
   218→  
   219→  /**
   220→   * Generate random number in range [min, max)
   221→   */
   222→  range(min: number, max: number): number {
   223→    return min + this.next() * (max - min);
   224→  }
   225→  
   226→  /**
   227→   * Generate random boolean with given probability
   228→   */
   229→  chance(probability: number): boolean {
   230→    return this.next() < probability;
   231→  }
   232→  
   233→  /**
   234→   * Choose random element from array
   235→   */
   236→  choose<T>(array: T[]): T {
   237→    return array[Math.floor(this.next() * array.length)];
   238→  }
   239→}
