   290→/**
   291→ * Core simulation engine
   292→ * 
   293→ * This engine is pure and deterministic - given the same initial state and seed,
   294→ * it will always produce the same results. This is critical for:
   295→ * - Reproducible testing
   296→ * - Monte Carlo simulations
   297→ * - Parameter sweeps
   298→ */
   299→export class SimulationEngine {
   300→  private rng: SeededRandom;
   301→  private config: SimulationConfig;
   302→  private orchestrator: PhaseOrchestrator;
   303→
   304→  constructor(config: SimulationConfig = {}) {
   305→    this.config = {
   306→      seed: config.seed ?? Date.now(),
   307→      maxMonths: config.maxMonths ?? 1000,
   308→      governmentActionFrequency: config.governmentActionFrequency ?? 0.5, // Default: 1 action per 2 months
   309→      socialAdaptationRate: config.socialAdaptationRate ?? 1.0,
   310→      aiCoordinationMultiplier: config.aiCoordinationMultiplier ?? 1.0,
   311→      economicTransitionRate: config.economicTransitionRate ?? 1.0,
   312→      snapshotInterval: config.snapshotInterval ?? 12  // Default to quarterly snapshots
   313→    };
   314→
   315→    this.rng = new SeededRandom(this.config.seed!);
   316→
   317→    // Initialize Phase Orchestrator (Phase 4: Engine Orchestration)
   318→    this.orchestrator = new PhaseOrchestrator();
   319→
   320→    // Register all phase implementations
   321→    // Batch 1: Simple calculations (30.x)
   322→    this.orchestrator.registerPhase(new UnemploymentPhase());
   323→    this.orchestrator.registerPhase(new EconomicTransitionPhase());
   324→    this.orchestrator.registerPhase(new ParanoiaPhase());
   325→    this.orchestrator.registerPhase(new SocialStabilityPhase());
   326→    this.orchestrator.registerPhase(new QualityOfLifePhase());
   327→    this.orchestrator.registerPhase(new OutcomeProbabilitiesPhase());
   328→    this.orchestrator.registerPhase(new CrisisDetectionPhase());
   329→
   330→    // Batch 2: System updates (10.x - 21.x)
   331→    this.orchestrator.registerPhase(new GovernanceQualityPhase());
   332→    this.orchestrator.registerPhase(new UpwardSpiralsPhase());
   333→    this.orchestrator.registerPhase(new TechTreePhase());
   334→    this.orchestrator.registerPhase(new MeaningRenaissancePhase());
   335→    this.orchestrator.registerPhase(new ConflictResolutionPhase());
   336→    this.orchestrator.registerPhase(new DiplomaticAIPhase());
   337→    this.orchestrator.registerPhase(new NationalAIPhase());
   338→    this.orchestrator.registerPhase(new UBIPhase());
   339→    this.orchestrator.registerPhase(new SocialSafetyNetsPhase());
   340→    this.orchestrator.registerPhase(new InformationWarfarePhase());
   341→    this.orchestrator.registerPhase(new PowerGenerationPhase());
   342→    this.orchestrator.registerPhase(new MADDeterrencePhase());
   343→    this.orchestrator.registerPhase(new ResourceEconomyPhase());
   344→    this.orchestrator.registerPhase(new ResourceTechnologyPhase());
   345→    this.orchestrator.registerPhase(new GeoengineringPhase());
   346→    this.orchestrator.registerPhase(new DefensiveAIPhase());
   347→    this.orchestrator.registerPhase(new PhosphorusPhase());
   348→    this.orchestrator.registerPhase(new FreshwaterPhase());
   349→    this.orchestrator.registerPhase(new OceanAcidificationPhase());
   350→    this.orchestrator.registerPhase(new NovelEntitiesPhase());
   351→    this.orchestrator.registerPhase(new HumanPopulationPhase());
   352→    this.orchestrator.registerPhase(new RefugeeCrisisPhase());
   353→    this.orchestrator.registerPhase(new CountryPopulationPhase());
   354→    this.orchestrator.registerPhase(new WarMeaningFeedbackPhase());  // TIER 2.8: War-Meaning Feedback Loop
   355→    this.orchestrator.registerPhase(new ClimateJusticePhase());  // TIER 2.8: Climate Justice & Environmental Debt
   356→    this.orchestrator.registerPhase(new OrganizationViabilityPhase());  // TIER 1.7.3: Check org survival vs country health
   357→    this.orchestrator.registerPhase(new NuclearWinterPhase());  // TIER 1.7.4: Update nuclear winter effects
   358→    this.orchestrator.registerPhase(new RadiationSystemPhase());  // TIER 1.7: Radiation health effects (cancer, birth defects, contamination)
   359→    this.orchestrator.registerPhase(new PlanetaryBoundariesPhase());
   360→    this.orchestrator.registerPhase(new FamineSystemPhase());  // FIX (Oct 13, 2025): Was missing!
   361→    this.orchestrator.registerPhase(new DystopiaProgressionPhase());
   362→
   363→    // Batch 3: Special phases (22.x - 23.x)
   364→    this.orchestrator.registerPhase(new BenchmarkEvaluationsPhase());
   365→    this.orchestrator.registerPhase(new CrisisPointsPhase());
   366→
   367→    // Batch 4: Agent/Infrastructure phases (1.0 - 10.0)
   368→    this.orchestrator.registerPhase(new ComputeGrowthPhase());
   369→    this.orchestrator.registerPhase(new OrganizationTurnsPhase());
   370→    this.orchestrator.registerPhase(new ComputeAllocationPhase());
   371→    this.orchestrator.registerPhase(new AILifecyclePhase());
   372→    this.orchestrator.registerPhase(new CyberSecurityPhase());
   373→    this.orchestrator.registerPhase(new SleeperWakePhase());
   374→    this.orchestrator.registerPhase(new AIAgentActionsPhase());
   375→    this.orchestrator.registerPhase(new TechnologyBreakthroughsPhase());
   376→    this.orchestrator.registerPhase(new GovernmentActionsPhase());
   377→    this.orchestrator.registerPhase(new SocietyActionsPhase());
   378→
   379→    // Batch 5: Final phases (37.0 - 40.0, 98.0 - 99.0)
   380→    this.orchestrator.registerPhase(new ExtinctionTriggersPhase());
   381→    this.orchestrator.registerPhase(new ExtinctionProgressPhase());
   382→    this.orchestrator.registerPhase(new TechnologyDiffusionPhase());
   383→    this.orchestrator.registerPhase(new CatastrophicScenariosPhase());
   384→    this.orchestrator.registerPhase(new EventCollectionPhase());
   385→    this.orchestrator.registerPhase(new TimeAdvancementPhase());
   386→  }
   387→  
   388→  /**
   389→   * Step the simulation forward by one month
   390→   *
   391→   * This is the core simulation loop powered by the PhaseOrchestrator.
   392→   * All game logic is now organized into phases that execute in order.
   393→   *
   394→   * Execution order (37 phases total):
   395→   * 1.0 - 10.0: Agent/Infrastructure (compute, AI lifecycle, actions)
   396→   * 11.0 - 21.0: System updates (governance, spirals, resources, etc.)
   397→   * 22.0 - 23.0: Special phases (benchmarks, crisis points)
   398→   * 30.0 - 36.0: Metric calculations (unemployment, QoL, outcomes, crisis)
   399→   * 37.0 - 40.0: Extinction and catastrophes
   400→   * 98.0 - 99.0: Event collection and time advancement
   401→   */
   402→  step(state: GameState): SimulationStepResult {
   403→    // Use state directly - phases are designed to mutate it
   404→    // Shallow copy breaks Set/Map objects in tech tree state
   405→    let newState = state;
   406→
   407→    // Use bound RNG for deterministic actions
   408→    const rng = this.rng.next.bind(this.rng);
   409→
   410→    // Execute all 37 phases in order via orchestrator
   411→    // Phases handle all game logic: agent actions, system updates, calculations, etc.
   412→    // See PhaseOrchestrator for execution order and phase list
   413→    const events = this.orchestrator.executeAll(newState, rng);
   414→
   415→    // Calculate final metrics for return value
   416→    // (All state updates are done by phases - we're just reading for the result)
   417→    const crisis = detectCrisis(newState);
   418→    const metrics = {
   419→      qualityOfLife: newState.globalMetrics.qualityOfLife,
   420→      effectiveControl: calculateEffectiveControl(newState),
   421→      unemployment: newState.society.unemploymentLevel,
   422→      outcomeProbs: newState.outcomeMetrics,
   423→      totalAICapability: calculateTotalAICapability(newState.aiAgents),
   424→      avgAlignment: calculateAverageAlignment(newState.aiAgents),
   425→      crisisDetected: crisis.inCrisis
   426→    };
   427→
   428→    return {
   429→      state: newState,
   430→      events,
   431→      metrics
   432→    };
   433→  }
   434→
   435→  /**
   436→   * Create a deep snapshot of game state, preserving Map and Set objects
   437→   * Uses structuredClone (modern API) which handles complex objects correctly
   438→   */
   439→  private snapshotState(state: GameState): GameState {
   440→    try {
   441→      // structuredClone is available in Node 17+ and modern browsers
   442→      // It correctly handles Map, Set, Date, RegExp, etc.
   443→      return structuredClone(state);
   444→    } catch (error) {
   445→      // Fallback for older Node versions: manual reconstruction
   446→      console.warn('structuredClone not available, using manual snapshot');
   447→
   448→      // Create shallow copy
   449→      const snapshot = { ...state };
   450→
   451→      // Deep clone arrays
   452→      snapshot.aiAgents = state.aiAgents.map(ai => ({ ...ai }));
   453→      snapshot.organizations = state.organizations.map(org => ({ ...org }));
   454→      snapshot.eventLog = [...state.eventLog];
   455→
   456→      // Preserve Map objects
   457→      if (state.computeInfrastructure?.computeAllocations) {
   458→        snapshot.computeInfrastructure = {
   459→          ...state.computeInfrastructure,
   460→          computeAllocations: new Map(state.computeInfrastructure.computeAllocations)
   461→        };
   462→      }
   463→
   464→      // Preserve Set objects
   465→      if (state.radiationSystem?.contaminatedRegions) {
   466→        snapshot.radiationSystem = {
   467→          ...state.radiationSystem,
   468→          contaminatedRegions: new Set(state.radiationSystem.contaminatedRegions)
   469→        };
   470→      }
   471→
   472→      if (state.biodiversitySystem?.regions) {
   473→        snapshot.biodiversitySystem = {
   474→          ...state.biodiversitySystem,
   475→          regions: new Map(state.biodiversitySystem.regions),
   476→          regionalWeights: new Map(state.biodiversitySystem.regionalWeights)
   477→        };
   478→      }
   479→
   480→      return snapshot;
   481→    }
   482→  }
   483→
   484→  /**
   485→   * Run simulation until a stop condition is met
   486→   */
   487→  run(initialState: GameState, stopConditions?: {
   488→    maxMonths?: number;
   489→    checkActualOutcomes?: boolean; // Stop when ACTUAL outcomes occur (not probabilities)
   490→  }): SimulationRunResult {
   491→    const maxMonths = stopConditions?.maxMonths ?? this.config.maxMonths!;
   492→    const checkActualOutcomes = stopConditions?.checkActualOutcomes ?? true;
   493→    const logLevel = this.config.logLevel ?? 'quartile';
   494→    
   495→    // Reset crisis points for this run
   496→    const { resetCrisisPoints } = require('./crisisPoints');
   497→    resetCrisisPoints();
   498→    
   499→    // Initialize logger with estimated duration
   500→    const logger = new SimulationLogger(this.config.seed!, logLevel, maxMonths);
   501→    const diagnosticLogger = new DiagnosticLogger();
   502→    const eventAggregator = new EventAggregator(12); // Report every 12 months
   503→    
   504→    let state = initialState;
   505→    const history: SimulationStepResult[] = [];
   506→    let actualOutcome: 'utopia' | 'dystopia' | 'extinction' | null = null;
   507→    let actualOutcomeReason: string = '';
   508→    
   509→    // Phase 3: Initialize end-game state if not present
   510→    if (!state.endGameState) {
   511→      state.endGameState = initializeEndGameState();
   512→    }
   513→    
   514→    const snapshotInterval = this.config.snapshotInterval ?? 12; // Default: snapshot every 12 months
   515→
   516→    for (let month = 0; month < maxMonths; month++) {
   517→      const stepResult = this.step(state);
   518→
   519→      // Snapshot state at configured intervals to preserve history
   520→      // This is expensive, so we do it sparingly (default: every 12 months)
   521→      if (month % snapshotInterval === 0 || month === maxMonths - 1) {
   522→        history.push({
   523→          ...stepResult,
   524→          state: this.snapshotState(state)
   525→        });
   526→      }
   527→
   528→      state = stepResult.state;
   529→      
   530→      // Attach aggregator to state for phases to use
   531→      (state as any).eventAggregator = eventAggregator;
   532→      
