    50→   * Execution order (lower numbers run first)
    51→   * Use decimals for fine-grained ordering (e.g., 0.5, 1.0, 1.5)
    52→   */
    53→  readonly order: number;
    54→
    55→  /**
    56→   * Execute this phase
    57→   *
    58→   * @param state - Current game state (may be mutated)
    59→   * @param rng - Random number generator function
    60→   * @param context - Optional context from previous phases
    61→   * @returns Phase result with events and optional new state
    62→   */
    63→  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult;
    64→}
    65→
    66→/**
    67→ * Context shared between phases during a single step
    68→ */
    69→export interface PhaseContext {
    70→  /**
    71→   * Current month being simulated
    72→   */
    73→  month: number;
    74→
    75→  /**
    76→   * Logger instance (if available)
    77→   */
    78→  logger?: any;
    79→
    80→  /**
    81→   * Arbitrary data that phases can use to communicate
    82→   */
    83→  data: Map<string, any>;
    84→}
    85→
    86→/**
    87→ * Orchestrates simulation phases in correct order
    88→ */
    89→export class PhaseOrchestrator {
    90→  private phases: SimulationPhase[] = [];
    91→  private sorted: boolean = false;
    92→
    93→  /**
    94→   * Register a phase
    95→   */
    96→  registerPhase(phase: SimulationPhase): void {
    97→    this.phases.push(phase);
    98→    this.sorted = false; // Mark as needing re-sort
    99→  }
   100→
   101→  /**
   102→   * Register multiple phases at once
   103→   */
   104→  registerPhases(phases: SimulationPhase[]): void {
   105→    this.phases.push(...phases);
   106→    this.sorted = false;
   107→  }
   108→
   109→  /**
   110→   * Execute all phases in order
   111→   *
   112→   * @param state - Game state (will be mutated)
   113→   * @param rng - Random number generator
   114→   * @param context - Optional context (created if not provided)
   115→   * @returns All events generated by phases
   116→   */
   117→  executeAll(state: GameState, rng: RNGFunction, context?: PhaseContext): GameEvent[] {
   118→    // Ensure phases are sorted by order
   119→    if (!this.sorted) {
   120→      this.sortPhases();
   121→    }
   122→
   123→    // Create context if not provided
   124→    const ctx: PhaseContext = context || {
   125→      month: state.currentMonth,
   126→      data: new Map()
   127→    };
   128→
   129→    const allEvents: GameEvent[] = [];
   130→
   131→    for (const phase of this.phases) {
   132→      try {
   133→        const result = phase.execute(state, rng, ctx);
   134→
   135→        // Collect events
   136→        if (result.events && result.events.length > 0) {
   137→          allEvents.push(...result.events);
   138→        }
   139→
   140→        // Handle state replacement (some phases return new state)
   141→        if (result.newState) {
   142→          // Copy properties from new state to current state
   143→          Object.assign(state, result.newState);
   144→        }
   145→
   146→        // Store metadata in context for later phases
   147→        if (result.metadata) {
   148→          ctx.data.set(phase.id, result.metadata);
   149→        }
   150→      } catch (error) {
   151→        console.error(`\n❌ ERROR in phase "${phase.name}" (${phase.id}):`, error);
   152→        // Continue with other phases to avoid complete simulation failure
   153→        // This matches current engine behavior (some phases have try/catch)
   154→      }
   155→    }
   156→
   157→    return allEvents;
   158→  }
   159→
   160→  /**
   161→   * Get execution order (for debugging/documentation)
   162→   */
   163→  getExecutionOrder(): string[] {
   164→    if (!this.sorted) {
   165→      this.sortPhases();
   166→    }
   167→    return this.phases.map(p => `[${p.order}] ${p.name} (${p.id})`);
   168→  }
   169→
   170→  /**
   171→   * Get phase count
   172→   */
   173→  getPhaseCount(): number {
   174→    return this.phases.length;
   175→  }
   176→
   177→  /**
   178→   * Get phase by ID
   179→   */
   180→  getPhase(id: string): SimulationPhase | undefined {
   181→    return this.phases.find(p => p.id === id);
   182→  }
   183→
   184→  /**
   185→   * Clear all registered phases (useful for testing)
   186→   */
   187→  clear(): void {
   188→    this.phases = [];
   189→    this.sorted = false;
   190→  }
   191→
   192→  /**
   193→   * Sort phases by order
   194→   */
   195→  private sortPhases(): void {
   196→    this.phases.sort((a, b) => {
   197→      // Primary sort: by order
   198→      if (a.order !== b.order) {
   199→        return a.order - b.order;
   200→      }
   201→      // Secondary sort: by name (for stability)
   202→      return a.name.localeCompare(b.name);
   203→    });
   204→    this.sorted = true;
   205→  }
   206→}
