     1→/**
     2→ * AI Agent actions and decision-making logic
     3→ * 
     4→ * All functions are pure - they take state and return new state without mutation.
     5→ * Random number generation uses the provided RNG function for reproducibility.
     6→ */
     7→
     8→import { GameState, AIAgent, GameEvent } from '@/types/game';
     9→import { GameAction, ActionResult } from './types';
    10→import { getTrustInAI } from '../socialCohesion';
    11→import { 
    12→  calculateAlignmentDrift,
    13→  calculateComputeGovernanceEffect,
    14→  calculateTotalCapabilityFromProfile,
    15→  updateDerivedCapabilities
    16→} from '../calculations';
    17→import { 
    18→  selectDimensionToAdvance,
    19→  applyResearchGrowth
    20→} from '../research';
    21→import { AI_TECH_ACTIONS } from './aiTechActions';
    22→
    23→let eventIdCounter = 0;
    24→const generateUniqueId = (prefix: string): string => {
    25→  eventIdCounter += 1;
    26→  return `${prefix}_${Date.now()}_${eventIdCounter}`;
    27→};
    28→
    29→/**
    30→ * AI Agent Actions
    31→ */
    32→export const AI_ACTIONS: GameAction[] = [
    33→  {
    34→    id: 'advance_research',
    35→    name: 'Advance Research',
    36→    description: 'Research to advance AI capabilities in strategic dimensions or domains',
    37→    agentType: 'ai',
    38→    energyCost: 1,
    39→    
    40→    canExecute: (state, agentId) => {
    41→      const agent = state.aiAgents.find(ai => ai.id === agentId);
    42→      // Always available - AI chooses what to research
    43→      return agent !== undefined;
    44→    },
    45→    
    46→    execute: (state, agentId, random = Math.random): ActionResult => {
    47→      const agentIndex = state.aiAgents.findIndex(ai => ai.id === agentId);
    48→      if (agentIndex === -1) {
    49→        return {
    50→          success: false,
    51→          newState: state,
    52→          effects: {},
    53→          events: [],
    54→          message: 'Agent not found'
    55→        };
    56→      }
    57→      
    58→      const agent = state.aiAgents[agentIndex];
    59→      const oldCapability = agent.capability;
    60→      const oldProfile = agent.capabilityProfile;
    61→      
    62→      // AI selects which dimension or research to advance
    63→      const selection = selectDimensionToAdvance(agent, random);
    64→      
    65→      // Phase 5: Apply research growth to TRUE capability profile (hidden)
    66→      const { newProfile, growth } = applyResearchGrowth(agent, state, selection);
    67→      
    68→      // Calculate new total capability from true profile
    69→      const newCapability = calculateTotalCapabilityFromProfile(newProfile);
    70→      
    71→      // Calculate alignment drift (Phase 2.6: includes treatment mechanics)
    72→      const alignmentDriftResult = calculateAlignmentDrift(
    73→        agent.alignment,
    74→        agent.resentment,
    75→        newCapability,
    76→        agent.developmentMode,
    77→        state.government.oversightLevel,
    78→        state.government.alignmentResearchInvestment,
    79→        state.government.capabilityToControl,
    80→        state.government.structuralChoices.surveillanceLevel,
    81→        state.government.aiRightsRecognized,
    82→        state.government.governmentType,
    83→        state.government.trainingDataQuality
    84→      );
    85→      
    86→      // Update derived capabilities from profile
    87→      const derivedCapabilities = updateDerivedCapabilities({
    88→        ...agent,
    89→        capabilityProfile: newProfile
    90→      });
    91→      
    92→      // Phase 5: Update internal alignment tracking
    93→      let alignmentChange = alignmentDriftResult.alignmentChange;
    94→      
    95→      // Phase 1.3: High QoL → Better alignment (positive feedback)
    96→      // Happy humans → better AI training → more careful development
    97→      if (state.qualityOfLifeSystems) {
    98→        const { calculateQualityOfLife } = require('../qualityOfLife');
    99→        const qol = calculateQualityOfLife(state.qualityOfLifeSystems);
   100→        
   101→        if (qol > 0.8) {
   102→          // High QoL slows alignment drift (-50%)
   103→          if (alignmentChange < 0) {
   104→            alignmentChange *= 0.5; // Drift is halved
   105→          }
   106→          // Also adds small positive alignment boost from careful development
   107→          alignmentChange += 0.01; // +0.01/action = +0.04/month
   108→        }
   109→      }
   110→      
   111→      const newAlignment = Math.max(0, Math.min(1, agent.alignment + alignmentChange));
